  local cfg_dir="$HOME/.config/ghostty"
  mkdir -p "$cfg_dir/themes"

  # Write fallback catppuccin-mocha theme file so both casing styles work seamlessly
  backup_file "$cfg_dir/themes/catppuccin-mocha"
  cat > "$cfg_dir/themes/catppuccin-mocha" << 'MOCHA_THEME'
palette = 0=#45475a
palette = 1=#f38ba8
palette = 2=#a6e3a1
palette = 3=#f9e2af
palette = 4=#89b4fa
palette = 5=#f5c2e7
palette = 6=#94e2d5
palette = 7=#a6adc8
palette = 8=#585b70
palette = 9=#f37799
palette = 10=#89d88b
palette = 11=#ebd391
palette = 12=#74a8fc
palette = 13=#f2aede
palette = 14=#6bd7ca
palette = 15=#bac2de
background = #1e1e2e
foreground = #cdd6f4
cursor-color = #f5e0dc
