MOCHA_THEME
  hts_track_file "$cfg_dir/themes/catppuccin-mocha"

  log "Writing Ghostty aesthetic configuration ($cfg_dir/config)..."
  backup_file "$cfg_dir/config"
  cat > "$cfg_dir/config" << 'GHOSTTY_CFG'
