  gobuster dns -d "$domain" -w "$wl" -t 50
}

sec-doctor() {
  # '--full' delegates to the installer's complete audit when its script is known
  if [[ "$1" == "--full" ]]; then
    if [[ -n "${HTS_TER_SH:-}" && -f "$HTS_TER_SH" ]]; then
      bash "$HTS_TER_SH" --doctor
    else
      echo "Full audit: run 'bash ter.sh --doctor' from the installer checkout (or set HTS_TER_SH=/path/to/ter.sh)."
    fi
    return
  fi
  echo ""
  echo "  ╔══ Quick Tool Check (~30 tools) — not the full installer audit ═╗"
  _doc() {
    local label=$1 cmd=$2
    if command -v "$cmd" &>/dev/null; then
      printf "  ║  \033[0;32m[✓]\033[0m %-22s \033[2m%s\033[0m\n" "$label" "$($cmd --version 2>/dev/null | head -1 | cut -c1-30)"
    else
      printf "  ║  \033[0;31m[✗]\033[0m %-22s \033[1;33mnot found\033[0m\n" "$label"
    fi
  }
  _doc "Node.js" "node"
  _doc "npm" "npm"
  _doc "Claude Code" "claude"
